3. const quizData = [
4.   {
5.     id: 'q1',
6.     legend: 'Which of the following languages use C-style curly-brace syntax?',
7.     helpText: 'Select all that apply. C-style syntax uses curly braces { } to delimit blocks instead of keywords like "end" or significant indentation.',
8.     helpId: 'q1-help',
9.     options: [
10.       { value: 'javascript', label: 'JavaScript', correct: true  },
11.       { value: 'python',     label: 'Python',     correct: false },
12.       { value: 'java',       label: 'Java',       correct: true  },
13.       { value: 'ruby',       label: 'Ruby',       correct: false },
14.     ],
15.   },
16.   {
17.     id: 'q2',
18.     legend: 'Which of the following languages were created by Google?',
19.     options: [
20.       { value: 'go',         label: 'Go',         correct: true  },
21.       { value: 'dart',       label: 'Dart',       correct: true  },
22.       { value: 'typescript', label: 'TypeScript', correct: false },
23.       { value: 'kotlin',     label: 'Kotlin',     correct: false },
24.     ],
25.   },
26.   {
27.     id: 'q3',
28.     legend: 'Which languages are primarily used for systems programming?',
29.     options: [
30.       { value: 'c',          label: 'C',          correct: true  },
31.       { value: 'rust',       label: 'Rust',       correct: true  },
32.       { value: 'javascript', label: 'JavaScript', correct: false },
33.       { value: 'php',        label: 'PHP',        correct: false },
34.     ],
35.   },
36. ];
37. 
38. // ─── Components (each returns a DOM node) ─────────────────────────────────────
39. 
40. /**
41.  * A single checkbox input + label pair.
42.  * @param {{ questionId: string, value: string, label: string }} props
43.  */
44. function CheckboxOption({ questionId, value, label }) {
45.   const inputId = `${questionId}-${value}`;
46. 
47.   const wrapper = document.createElement('div');
48.   wrapper.className = 'checkbox-option';
49. 
50.   const input = document.createElement('input');
51.   input.type = 'checkbox';
52.   input.id = inputId;
53.   input.name = questionId;
54.   input.value = value;
55. 
56.   // Clicking anywhere in the row toggles the checkbox
57.   wrapper.addEventListener('click', (e) => {
58.     if (e.target !== input) input.click();
59.   });
60.   // Prevent double-toggle when clicking the label itself
61.   wrapper.addEventListener('click', (e) => {
62.     if (e.target.tagName === 'LABEL') e.preventDefault();
63.   });
64. 
65.   const labelEl = document.createElement('label');
66.   labelEl.htmlFor = inputId;
67.   labelEl.textContent = label;
68. 
69.   wrapper.appendChild(input);
70.   wrapper.appendChild(labelEl);
71.   return wrapper;
72. }
73. 
74. /**
75.  * A labeled, optionally described checkbox group wrapped in a <fieldset>.
76.  * @param {{ id: string, legend: string, helpText?: string, helpId?: string, options: object[] }} props
77.  */
78. function CheckboxGroup({ id, legend, helpText, helpId, options }) {
79.   const fieldset = document.createElement('fieldset');
80.   if (helpId) {
81.     fieldset.setAttribute('aria-describedby', helpId);
82.   }
83. 
84.   const legendEl = document.createElement('legend');
85.   legendEl.textContent = legend;
86.   fieldset.appendChild(legendEl);
87. 
88.   if (helpText && helpId) {
89.     const help = document.createElement('p');
90.     help.id = helpId;
91.     help.className = 'field-help';
92.     help.textContent = helpText;
93.     fieldset.appendChild(help);
94.   }
95. 
96.   const optionsContainer = document.createElement('div');
97.   optionsContainer.className = 'checkbox-options';
98.   options.forEach((opt) => {
99.     optionsContainer.appendChild(CheckboxOption({ questionId: id, ...opt }));
100.   });
101.   fieldset.appendChild(optionsContainer);
102. 
103.   return fieldset;
104. }
105. 
106. /**
107.  * A card wrapper for a single quiz question.
108.  * @param {{ number: number, id: string, legend: string, helpText?: string, helpId?: string, options: object[] }} props
109.  */
110. function QuizQuestion({ number, ...groupProps }) {
111.   const card = document.createElement('div');
112.   card.className = 'form-field';
113. 
114.   // Prepend the question number into the legend text
115.   const legendWithNumber = `${number}. ${groupProps.legend}`;
116.   card.appendChild(CheckboxGroup({ ...groupProps, legend: legendWithNumber }));
117. 
118.   return card;
119. }
120. 
121. /**
122.  * An aria-live region that displays results after submission.
123.  */
124. function ResultsRegion() {
