 // ─── Components (each returns a DOM node) ─────────────────────────────────────

 /**
  * A single checkbox input + label pair.
  * @param {{ questionId: string, value: string, label: string }} props
  */
 function CheckboxOption({ questionId, value, label }) {
   const inputId = `${questionId}-${value}`;

   const wrapper = document.createElement('div');
   wrapper.className = 'checkbox-option';

   const input = document.createElement('input');
   input.type = 'checkbox';
   input.id = inputId;
   input.name = questionId;
   input.value = value;

   // Clicking anywhere in the row toggles the checkbox
   wrapper.addEventListener('click', (e) => {
     if (e.target !== input) input.click();
   });
   // Prevent double-toggle when clicking the label itself
   wrapper.addEventListener('click', (e) => {
     if (e.target.tagName === 'LABEL') e.preventDefault();
   });

   const labelEl = document.createElement('label');
   labelEl.htmlFor = inputId;
   labelEl.textContent = label;

   wrapper.appendChild(input);
   wrapper.appendChild(labelEl);
   return wrapper;
 }

 /**
  * A labeled, optionally described checkbox group wrapped in a <fieldset>.
  * @param {{ id: string, legend: string, helpText?: string, helpId?: string, options: object[] }} props
  */
 function CheckboxGroup({ id, legend, helpText, helpId, options }) {
   const fieldset = document.createElement('fieldset');
   if (helpId) {
     fieldset.setAttribute('aria-describedby', helpId);
   }

   const legendEl = document.createElement('legend');
   legendEl.textContent = legend;
   fieldset.appendChild(legendEl);

   if (helpText && helpId) {
     const help = document.createElement('p');
     help.id = helpId;
     help.className = 'field-help';
     help.textContent = helpText;
     fieldset.appendChild(help);
   }

   const optionsContainer = document.createElement('div');
   optionsContainer.className = 'checkbox-options';
   options.forEach((opt) => {
     optionsContainer.appendChild(CheckboxOption({ questionId: id, ...opt }));
   });
   fieldset.appendChild(optionsContainer);

   return fieldset;
 }

 /**
  * A card wrapper for a single quiz question.
  * @param {{ number: number, id: string, legend: string, helpText?: string, helpId?: string, options: object[] }} props
  */
 function QuizQuestion({ number, ...groupProps }) {
   const card = document.createElement('div');
   card.className = 'form-field';

   // Prepend the question number into the legend text
   const legendWithNumber = `${number}. ${groupProps.legend}`;
   card.appendChild(CheckboxGroup({ ...groupProps, legend: legendWithNumber }));

   return card;
 }

 /**
  * An aria-live region that displays results after submission.
  */
 function ResultsRegion() {
   const div = document.createElement('div');
   div.id = 'quiz-results';
   div.className = 'quiz-results';
   div.setAttribute('aria-live', 'polite');
   div.setAttribute('aria-atomic', 'true');
   return div;
 }

 /**
  * The full quiz form.
  * @param {{ questions: object[] }} props
  */
 function Quiz({ questions }) {
   const form = document.createElement('form');
   form.id = 'quiz-form';
   form.noValidate = true;

   questions.forEach((q, i) => {
     form.appendChild(QuizQuestion({ number: i + 1, ...q }));
   });

   const submitBtn = document.createElement('button');
   submitBtn.type = 'submit';
   submitBtn.className = 'submit-btn';
   submitBtn.textContent = 'Submit quiz';
   form.appendChild(submitBtn);

   const resultsEl = ResultsRegion();
   form.appendChild(resultsEl);

   form.addEventListener('submit', (e) => {
     e.preventDefault();
     handleSubmit(questions, form, resultsEl);
   });

   return form;
 }

 // ─── Submit handler ────────────────────────────────────────────────────────────

 /**
  * Scores the quiz and renders results into the live region.
  * @param {object[]} questions
  * @param {HTMLFormElement} form
  * @param {HTMLElement} resultsEl
  */
 function handleSubmit(questions, form, resultsEl) {
   let score = 0;

   const feedback = questions.map((q) => {
     const checked = [...form.querySelectorAll(`input[name="${q.id}"]:checked`)]
       .map((el) => el.value);
     const correct = q.options.filter((o) => o.correct).map((o) => o.value);
     const isCorrect =
       checked.length === correct.length && correct.every((v) => checked.includes(v));
     if (isCorrect) score++;
     return { q, isCorrect, checked, correct };
   });

   // ── Build result markup ──
   resultsEl.innerHTML = '';

   const heading = document.createElement('h2');
   heading.textContent = 'Results';
   resultsEl.appendChild(heading);

   // Score banner
   const banner = document.createElement('div');
   banner.className = 'score-banner';

   const scoreValue = document.createElement('span');
   scoreValue.className = 'score-value';
   scoreValue.setAttribute('aria-label', `Score: ${score} out of ${questions.length}`);
   scoreValue.textContent = `${score}/${questions.length}`;

   const scoreLabel = document.createElement('p');
   scoreLabel.className = 'score-label';
   scoreLabel.textContent =
     score === questions.length
       ? 'Perfect score — well done!'
       : score === 0
       ? 'Keep studying — you\'ll get there!'
       : 'Good effort! Review the answers below.';

   banner.appendChild(scoreValue);
   banner.appendChild(scoreLabel);
   resultsEl.appendChild(banner);

   // Per-question feedback
   feedback.forEach(({ q, isCorrect }) => {
     const item = document.createElement('div');
     item.className = `result-item ${isCorrect ? 'result-correct' : 'result-incorrect'}`;

     const questionText = document.createElement('p');
     questionText.className = 'result-question';
     questionText.textContent = q.legend;
     item.appendChild(questionText);

     const status = document.createElement('p');
     status.className = 'result-status';

     if (isCorrect) {
       status.textContent = '✓ Correct!';
     } else {
       const correctLabels = q.options
         .filter((o) => o.correct)
         .map((o) => o.label)
         .join(', ');
       status.textContent = `✗ Incorrect. Correct answer(s): ${correctLabels}`;
     }

     item.appendChild(status);
     resultsEl.appendChild(item);
   });

   // Move focus to the results heading so keyboard/SR users are notified
   heading.tabIndex = -1;
   heading.focus();
 }

 // ─── Mount ─────────────────────────────────────────────────────────────────────

 document.addEventListener('DOMContentLoaded', () => {
   document.getElementById('app').appendChild(Quiz({ questions: quizData }));
